//! Original combined shear/twist fold release into finite caloric receivers.
//!
//! Every loading segment and explicit separation is regenerated by the original
//! shared-radius source. Only its newly released total potential is partitioned;
//! signed prescribed work and all reversible stores remain mechanical. Earlier
//! release in an imported history cannot be deposited retroactively.
//!
//! This is a frozen-source impulse split at the current thermal time. It creates
//! no conducting contact, body impulse, physical loading clock, slip or rebonding
//! law. Reaching the first fold does not itself authorize an automatic release.

/// Prescribed temperature continuation with retained loading and caloric history.
pub mod temperature;
/// Prescribed physical loading time, finite transport and contact separation.
pub mod timed;

use super::{JkrSnapHeatControls, JkrSnapHeatError, Receiver};
use fs_blake3::ContentHash;
use fs_contact::normal_patch::adhesive::mixed_mode::combined::loading::{
    JkrCombinedLoading, JkrCombinedLoadingError, JkrCombinedLoadingReport, JkrCombinedLoadingState,
};
use fs_exec::CancelGate;
use fs_material::phase::EquilibriumEnthalpyPhaseCurve;
use fs_math::dd::Dd;
use fs_thermal::enthalpy::{CellId, DepositionError, DepositionSimulation, EnergyAudit};
use fs_tribo::{DissipationStep, HeatPartition, TriboError, WorkLedger};
use std::collections::BTreeMap;

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum JkrCombinedHeatSegment {
    /// Traverse the original proportional path only as far as its first boundary.
    LoadFactor(f64),
    /// Explicitly release an admitted separating radial fold at held coordinates.
    DetachAtFold,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct JkrCombinedHeatControls {
    /// Segment, caloric and contact-to-thermal transfer budgets.
    pub heat: JkrSnapHeatControls,
    /// Independent whole-transaction budget for mechanical and transfer defects.
    /// Source steps still enforce their own original constitutive tolerances.
    pub total_energy_tolerance_j: f64,
}

#[derive(Debug)]
pub enum JkrCombinedHeatError {
    Source(JkrCombinedLoadingError),
    Heat(JkrSnapHeatError),
    EnergyBalance {
        residual_j: f64,
        absolute_stage_residual_j: f64,
    },
}
impl From<JkrCombinedLoadingError> for JkrCombinedHeatError {
    fn from(error: JkrCombinedLoadingError) -> Self {
        Self::Source(error)
    }
}
impl From<JkrSnapHeatError> for JkrCombinedHeatError {
    fn from(error: JkrSnapHeatError) -> Self {
        Self::Heat(error)
    }
}
impl From<DepositionError> for JkrCombinedHeatError {
    fn from(error: DepositionError) -> Self {
        Self::Heat(error.into())
    }
}
impl From<TriboError> for JkrCombinedHeatError {
    fn from(error: TriboError) -> Self {
        Self::Heat(error.into())
    }
}
impl core::fmt::Display for JkrCombinedHeatError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        write!(f, "combined JKR loading heat: {self:?}")
    }
}
impl std::error::Error for JkrCombinedHeatError {}

/// Complete accepted original loading history and heat-binding revision.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct JkrCombinedHeatStamp {
    source: ContentHash,
    revision: u64,
    state: JkrCombinedLoadingState,
}
impl JkrCombinedHeatStamp {
    pub const fn state(self) -> JkrCombinedLoadingState {
        self.state
    }
}

#[derive(Clone)]
pub struct JkrCombinedHeat<'s> {
    loading: JkrCombinedLoading<'s>,
    caloric: [&'s EquilibriumEnthalpyPhaseCurve; 2],
    receivers: [Receiver; 2],
    partition: HeatPartition,
    outside_destination: Option<String>,
    stamp: JkrCombinedHeatStamp,
    accepted_time_s: f64,
    ledger: WorkLedger,
}

/// Observations, never accepted as mechanical or caloric authority on input.
#[derive(Clone, Debug, PartialEq)]
pub struct JkrCombinedHeatReport {
    pub source_identity: ContentHash,
    pub initial_state: JkrCombinedLoadingState,
    pub final_state: JkrCombinedLoadingState,
    /// Original ordered reports retain clipped prefixes and all four stores.
    pub segments: Vec<JkrCombinedLoadingReport>,
    pub prescribed_work_j: f64,
    pub storage_change_j: f64,
    pub released_energy_j: f64,
    /// Newly released energy and its explicitly declared destinations only.
    pub work: WorkLedger,
    pub outside_destination: Option<String>,
    /// Original relative finite-cell audit; its supplied heat is internal to
    /// the combined contact/thermal/outside account.
    pub thermal: EnergyAudit,
    pub mechanical_energy_residual_j: f64,
    pub absolute_mechanical_energy_residual_j: f64,
    /// Delta H + outside work - newly released original potential.
    pub transfer_residual_j: f64,
    pub absolute_transfer_residual_j: f64,
    /// Delta U_contact + Delta H + outside work - prescribed mechanical work.
    pub combined_energy_residual_j: f64,
    /// Constitutive, accumulation, partition and caloric errors cannot cancel.
    pub absolute_stage_energy_residual_j: f64,
}

pub struct JkrCombinedHeatCandidate<'s, 'm> {
    history: JkrCombinedHeat<'s>,
    thermal: DepositionSimulation<'m>,
    report: JkrCombinedHeatReport,
}
impl<'s, 'm> JkrCombinedHeatCandidate<'s, 'm> {
    pub const fn history(&self) -> &JkrCombinedHeat<'s> {
        &self.history
    }
    pub const fn thermal(&self) -> &DepositionSimulation<'m> {
        &self.thermal
    }
    pub const fn report(&self) -> &JkrCombinedHeatReport {
        &self.report
    }
    pub fn into_parts(
        self,
    ) -> (
        JkrCombinedHeat<'s>,
        DepositionSimulation<'m>,
        JkrCombinedHeatReport,
    ) {
        (self.history, self.thermal, self.report)
    }
}

impl<'s> JkrCombinedHeat<'s> {
    /// Bind an already loaded or separated original history to its exact
    /// registered caloric owners. Prior source release is retained in the state;
    /// the new transfer ledger starts at zero without changing either cell.
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        loading: JkrCombinedLoading<'s>,
        initial: JkrCombinedLoadingState,
        thermal: &DepositionSimulation<'_>,
        cells: [CellId; 2],
        caloric: [&'s EquilibriumEnthalpyPhaseCurve; 2],
        partition: HeatPartition,
        outside_destination: Option<String>,
        gate: &CancelGate,
    ) -> Result<Self, JkrCombinedHeatError> {
        if cells[0] == cells[1]
            || outside_destination
                .as_ref()
                .is_some_and(|name| name.trim().is_empty())
            || (partition.other() > 0.0 && outside_destination.is_none())
        {
            return Err(JkrSnapHeatError::Invalid(
                "distinct cells and named outside destination required",
            )
            .into());
        }
        DissipationStep::from_work(0.0, partition)?;
        // The original owner authenticates its private loading identity. Keep
        // the incoming state: even a no-travel source step advances its counter.
        loading.advance_to_load_factor(initial, initial.load_factor(), gate)?;
        let receivers =
            Receiver::capture(loading.source().normal_source(), thermal, cells, caloric)?;
        if gate.is_requested() {
            return Err(JkrCombinedLoadingError::Cancelled.into());
        }
        Ok(Self {
            loading,
            caloric,
            receivers,
            partition,
            outside_destination,
            stamp: JkrCombinedHeatStamp {
                source: loading.source().identity(),
                revision: 0,
                state: initial,
            },
            accepted_time_s: thermal.time_s(),
            ledger: WorkLedger::default(),
        })
    }

    pub const fn loading(&self) -> &JkrCombinedLoading<'s> {
        &self.loading
    }
    pub const fn state(&self) -> JkrCombinedLoadingState {
        self.stamp.state
    }
    pub const fn stamp(&self) -> JkrCombinedHeatStamp {
        self.stamp
    }
    pub const fn ledger(&self) -> &WorkLedger {
        &self.ledger
    }

    /// Regenerate every prescribed segment and stage one same-time caloric
    /// impulse. Reversals retain signed work; a boundary stop retains its
    /// untraversed prefix and remains attached until explicit admitted release.
    ///
    /// Thermal time may have advanced externally, but source coefficients stay
    /// frozen. Bounded source probes use `gate`; caller checkpoints bracket all
    /// source segments and caloric publication. Cost is linear in the segment
    /// count plus original source solves and one native thermal clone.
    #[allow(clippy::too_many_arguments, clippy::too_many_lines)]
    pub fn propose<'m>(
        &self,
        thermal: &DepositionSimulation<'m>,
        expected: JkrCombinedHeatStamp,
        segments: &[JkrCombinedHeatSegment],
        controls: JkrCombinedHeatControls,
        gate: &CancelGate,
        mut checkpoint: impl FnMut() -> Result<(), DepositionError>,
    ) -> Result<JkrCombinedHeatCandidate<'s, 'm>, JkrCombinedHeatError> {
        let mut check = || {
            if gate.is_requested() {
                return Err(DepositionError::Cancelled);
            }
            checkpoint()?;
            if gate.is_requested() {
                return Err(DepositionError::Cancelled);
            }
            Ok(())
        };
        check()?;
        if expected != self.stamp {
            return Err(JkrSnapHeatError::HistoryMismatch.into());
        }
        if segments.is_empty()
            || segments.len() > controls.heat.maximum_segments
            || thermal.time_s() < self.accepted_time_s
            || [
                controls.heat.cell_energy_tolerance_j,
                controls.heat.thermal_energy_tolerance_j,
                controls.heat.transfer_energy_tolerance_j,
                controls.total_energy_tolerance_j,
            ]
            .iter()
            .any(|v| !v.is_finite() || *v < 0.0)
        {
            return Err(JkrSnapHeatError::Invalid("invalid segment, clock or heat budget").into());
        }
        let revision = self
            .stamp
            .revision
            .checked_add(1)
            .ok_or(JkrSnapHeatError::Invalid("history version exhausted"))?;
        self.admit_receivers(thermal)?;
        let mut state = self.state();
        let mut reports = Vec::with_capacity(segments.len());
        let mut work = WorkLedger::default();
        let mut ledger = self.ledger;
        let mut prescribed = Dd::ZERO;
        let mut release = Dd::ZERO;
        let mut mechanical_stages = Dd::ZERO;
        let mut absolute_mechanical = Dd::ZERO;
        let mut partition_stages = Dd::ZERO;
        let mut absolute_partition = Dd::ZERO;
        for segment in segments {
            check()?;
            let step = match *segment {
                JkrCombinedHeatSegment::LoadFactor(factor) => {
                    self.loading.advance_to_load_factor(state, factor, gate)?
                }
                JkrCombinedHeatSegment::DetachAtFold => self.loading.detach_at_fold(state, gate)?,
            };
            let report = *step.report();
            let loss = DissipationStep::from_work(report.released_energy_j, self.partition)?;
            let partition =
                dd(loss.surface_a_heat_j()) + dd(loss.surface_b_heat_j()) + dd(loss.other_work_j())
                    - dd(report.released_energy_j);
            partition_stages = partition_stages + partition;
            absolute_partition = absolute_partition + partition.abs();
            let mechanical = dd(report.storage_change_j) + dd(report.released_energy_j)
                - dd(report.prescribed_work_j);
            mechanical_stages = mechanical_stages + mechanical;
            absolute_mechanical = absolute_mechanical + mechanical.abs();
            prescribed = prescribed + dd(report.prescribed_work_j);
            release = release + dd(report.released_energy_j);
            work.record(loss)?;
            ledger.record(loss)?;
            state = step.state();
            reports.push(report);
        }
        check()?;
        let storage = dd(state.stored_energy_j()) - dd(self.state().stored_energy_j());
        let mechanical = storage + release - prescribed;
        // Include any loss in telescoping rounded source increments separately
        // from the original per-stage constitutive balance defects.
        absolute_mechanical = absolute_mechanical + (mechanical - mechanical_stages).abs();
        let heat = BTreeMap::from([
            (self.receivers[0].cell, work.surface_a_heat_j()),
            (self.receivers[1].cell, work.surface_b_heat_j()),
        ]);
        let (next_thermal, audit) = thermal.apply_heat_j(
            &heat,
            controls.heat.cell_energy_tolerance_j,
            controls.heat.thermal_energy_tolerance_j,
            &mut check,
        )?;
        // Preserve each receiver's relative caloric defect in the total budget,
        // too. The thermal owner already gates their absolute sum against its
        // own allowance; that allowance need not be the total-energy allowance.
        let mut absolute_caloric = Dd::ZERO;
        for receiver in self.receivers {
            let before = &thermal.cells()[&receiver.cell];
            let after = &next_thermal.cells()[&receiver.cell];
            let change = receiver.mass_kg * (after.specific_h_j_kg - before.specific_h_j_kg);
            let defect = finite(change - heat[&receiver.cell])?;
            absolute_caloric = absolute_caloric + dd(defect.abs());
        }
        let thermal = next_thermal;
        let partition =
            dd(work.surface_a_heat_j()) + dd(work.surface_b_heat_j()) + dd(work.other_work_j())
                - release;
        let transfer = partition + dd(audit.residual_j);
        let absolute_transfer =
            absolute_partition + (partition - partition_stages).abs() + absolute_caloric;
        let transfer_residual_j = finite(transfer.to_f64())?;
        let absolute_transfer_residual_j = finite(absolute_transfer.to_f64())?;
        if transfer_residual_j.abs() > controls.heat.transfer_energy_tolerance_j
            || absolute_transfer_residual_j > controls.heat.transfer_energy_tolerance_j
        {
            return Err(JkrSnapHeatError::TransferBalance(
                transfer_residual_j.abs().max(absolute_transfer_residual_j),
            )
            .into());
        }
        let combined_energy_residual_j = finite((mechanical + transfer).to_f64())?;
        let absolute_stage_energy_residual_j =
            finite((absolute_mechanical + absolute_transfer).to_f64())?;
        if combined_energy_residual_j.abs() > controls.total_energy_tolerance_j
            || absolute_stage_energy_residual_j > controls.total_energy_tolerance_j
        {
            return Err(JkrCombinedHeatError::EnergyBalance {
                residual_j: combined_energy_residual_j,
                absolute_stage_residual_j: absolute_stage_energy_residual_j,
            });
        }
        let report = JkrCombinedHeatReport {
            source_identity: self.loading.source().identity(),
            initial_state: self.state(),
            final_state: state,
            segments: reports,
            prescribed_work_j: finite(prescribed.to_f64())?,
            storage_change_j: finite(storage.to_f64())?,
            released_energy_j: finite(release.to_f64())?,
            work,
            outside_destination: self.outside_destination.clone(),
            thermal: audit,
            mechanical_energy_residual_j: finite(mechanical.to_f64())?,
            absolute_mechanical_energy_residual_j: finite(absolute_mechanical.to_f64())?,
            transfer_residual_j,
            absolute_transfer_residual_j,
            combined_energy_residual_j,
            absolute_stage_energy_residual_j,
        };
        let mut history = self.clone();
        history.stamp.revision = revision;
        history.stamp.state = state;
        history.accepted_time_s = thermal.time_s();
        history.ledger = ledger;
        check()?;
        Ok(JkrCombinedHeatCandidate {
            history,
            thermal,
            report,
        })
    }

    /// Accept source history, cumulative transfer and both finite cells together.
    /// A late cancellation or source, caloric or balance refusal leaves the
    /// original owners intact and permits retry with the same accepted stamp.
    #[allow(clippy::too_many_arguments)]
    pub fn apply<'m>(
        &mut self,
        thermal: &mut DepositionSimulation<'m>,
        expected: JkrCombinedHeatStamp,
        segments: &[JkrCombinedHeatSegment],
        controls: JkrCombinedHeatControls,
        gate: &CancelGate,
        mut checkpoint: impl FnMut() -> Result<(), DepositionError>,
    ) -> Result<JkrCombinedHeatReport, JkrCombinedHeatError> {
        let (history, next, report) = self
            .propose(thermal, expected, segments, controls, gate, &mut checkpoint)?
            .into_parts();
        checkpoint()?;
        if gate.is_requested() {
            return Err(JkrCombinedLoadingError::Cancelled.into());
        }
        *self = history;
        *thermal = next;
        Ok(report)
    }

    fn admit_receivers(&self, thermal: &DepositionSimulation<'_>) -> Result<(), JkrSnapHeatError> {
        for (side, receiver) in self.receivers.iter().enumerate() {
            receiver.admit(thermal, self.caloric[side])?;
        }
        Ok(())
    }
}

fn dd(value: f64) -> Dd {
    Dd::from_f64(value)
}

fn finite(value: f64) -> Result<f64, JkrCombinedHeatError> {
    if value.is_finite() {
        Ok(value)
    } else {
        Err(JkrSnapHeatError::Invalid("finite combined mechanical/heat account").into())
    }
}
